 "content": "def transform(grid):
    # Fill the interior of hollow rectangular frames, with color determined by
    # the separate 3x3 marker (its center color).
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=sum(row.count(v) for row in grid))
    frames = {}
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r,c) in frames: continue
            # connected components
            stack=[(r,c)]; seen={(r,c)}
            while stack:
                y,x=stack.pop()
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            for p in seen: frames[p]=1
            ys=[p[0] for p in seen]; xs=[p[1] for p in seen]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            if len(seen)==2*(y1-y0+x1-x0):
                # identify marker square elsewhere; use its center cell color
                marker=None
                for yy in range(h-2):
                    for xx in range(w-2):
                        vals=[grid[a][b] for a in range(yy,yy+3) for b in range(xx,xx+3)]
                        if vals[4] != bg and vals[4] != col and all(vals[i] in (bg,vals[4]) for i in range(9)) and vals.count(vals[4])==8:
                            marker=vals[4]
                if marker is not None:
                    for yy in range(y0+1,y1):
                        for xx in range(x0+1,x1): out[yy][xx]=marker
    # For irregular hollow frame, bounds fill interior as well.
    return out
"
